    ('warrior', 'warrior:BASH', 'BASH', 540, 55, 0, '{"in_combat": true, "level_scaled_chance": true, "requires_shield": true}', 'auto', true),
    ('warrior', 'warrior:KICK', 'KICK', 550, 100, 0, '{"in_combat": true, "level_scaled_chance": true}', 'auto', true),
    ('warrior', 'warrior:BODYSLAM', 'BODYSLAM', 510, 50, 0, '{"level_scaled_chance": true, "out_of_combat": true}', 'auto', true),
    ('sorcerer', 'sorcerer:ANIMATE_DEAD', 'ANIMATE_DEAD', 150, 100, 0, '{"out_of_combat": true}', 'room', true),
    ('rogue', 'rogue:HIDE', 'HIDE', 100, 100, 0, '{"out_of_combat": true}', 'self', true)
), raw AS (
    SELECT cf.class_name || '/' || fr.rule_key AS seed_key, c.id AS class_id, a.id AS ability_id,
           fr.priority::int AS priority, fr.chance_pct::int AS chance_pct, fr.cooldown_s::int AS cooldown_s,
           fr.conditions::jsonb AS conditions, fr.target AS target, cs.min_level AS min_level,
           fr.enabled AS enabled
    FROM class_family cf
    JOIN family_rule fr ON fr.family = cf.family
    JOIN "Class" c ON c.plain_name = cf.class_name
    JOIN "Ability" a ON a.plain_name = fr.ability_name
    LEFT JOIN "ClassSkills" cs ON cs.class_id = c.id AND cs.ability_id = a.id
    LEFT JOIN "ClassAbilities" ca ON ca.class_id = c.id AND ca.ability_id = a.id
    WHERE cs.id IS NOT NULL OR ca.id IS NOT NULL
), seed AS (
    SELECT raw.*, md5(concat_ws('|', raw.ability_id, raw.priority, raw.chance_pct, raw.cooldown_s, coalesce(raw.conditions::text, ''), raw.target, coalesce(raw.min_level::text, ''), CASE WHEN raw.enabled IS FALSE THEN 'off' END)) AS seed_hash FROM raw
)
UPDATE "ClassAiRules" r SET seed_key = s.seed_key, seed_hash = md5(concat_ws('|', r.ability_id, r.priority, r.chance_pct, r.cooldown_s, coalesce(r.conditions::text, ''), r.target, coalesce(r.min_level::text, ''), CASE WHEN r.enabled IS FALSE THEN 'off' END))
FROM seed s
WHERE r.seed_key IS NULL AND r.class_id = s.class_id AND r.ability_id = s.ability_id
  AND r.priority = s.priority AND r.chance_pct = s.chance_pct
  AND r.target = s.target AND r.min_level IS NOT DISTINCT FROM s.min_level
  AND (r.cooldown_s = s.cooldown_s OR r.cooldown_s = 0)
  AND (r.conditions IS NOT DISTINCT FROM s.conditions
       OR (s.conditions ->> 'cooldown_group' IS NOT NULL
           AND r.conditions IS NOT DISTINCT FROM NULLIF(s.conditions - 'cooldown_group', '{}'::jsonb)))
  AND NOT EXISTS (SELECT 1 FROM "ClassAiRules" k WHERE k.seed_key = s.seed_key);

