    ('warrior', 'warrior:BACKSTAB', 'BACKSTAB', 530, 4, 0, '{"in_combat": true, "level_scaled_chance": true, "requires_weapon_type": "piercing"}', 'auto', true),
    ('warrior', 'warrior:BASH', 'BASH', 540, 55, 0, '{"in_combat": true, "level_scaled_chance": true, "requires_shield": true}', 'auto', true),
    ('warrior', 'warrior:KICK', 'KICK', 550, 100, 0, '{"in_combat": true, "level_scaled_chance": true}', 'auto', true)
), raw AS (
    SELECT cf.class_name || '/' || fr.rule_key AS seed_key, c.id AS class_id, a.id AS ability_id,
           fr.priority::int AS priority, fr.chance_pct::int AS chance_pct, fr.cooldown_s::int AS cooldown_s,
           fr.conditions::jsonb AS conditions, fr.target AS target, cs.min_level AS min_level,
           fr.enabled AS enabled
    FROM class_family cf
    JOIN family_rule fr ON fr.family = cf.family
    JOIN "Class" c ON c.plain_name = cf.class_name
    JOIN "Ability" a ON a.plain_name = fr.ability_name
    LEFT JOIN "ClassSkills" cs ON cs.class_id = c.id AND cs.ability_id = a.id
    LEFT JOIN "ClassAbilities" ca ON ca.class_id = c.id AND ca.ability_id = a.id
    WHERE cs.id IS NOT NULL OR ca.id IS NOT NULL
), seed AS (
    SELECT raw.*, md5(concat_ws('|', raw.ability_id, raw.priority, raw.chance_pct, raw.cooldown_s, coalesce(raw.conditions::text, ''), raw.target, coalesce(raw.min_level::text, ''), CASE WHEN raw.enabled IS FALSE THEN 'off' END)) AS seed_hash FROM raw
)
INSERT INTO "ClassAiRules" (class_id, ability_id, priority, chance_pct, cooldown_s, conditions,
    target, min_level, enabled, seed_key, seed_hash)
SELECT s.class_id, s.ability_id, s.priority, s.chance_pct, s.cooldown_s, s.conditions,
       s.target, s.min_level, s.enabled, s.seed_key, s.seed_hash
FROM seed s
WHERE NOT EXISTS (SELECT 1 FROM "ClassAiRules" x WHERE x.class_id = s.class_id AND x.ability_id = s.ability_id
                  AND x.priority = s.priority AND x.seed_key IS DISTINCT FROM s.seed_key)
ON CONFLICT (seed_key) DO UPDATE SET
    ability_id = EXCLUDED.ability_id, priority = EXCLUDED.priority, chance_pct = EXCLUDED.chance_pct,
    cooldown_s = EXCLUDED.cooldown_s, conditions = EXCLUDED.conditions, target = EXCLUDED.target,
    min_level = EXCLUDED.min_level, seed_hash = EXCLUDED.seed_hash,
    enabled = "ClassAiRules".enabled AND EXCLUDED.enabled
WHERE "ClassAiRules".seed_hash IS NOT DISTINCT FROM md5(concat_ws('|', "ClassAiRules".ability_id, "ClassAiRules".priority, "ClassAiRules".chance_pct, "ClassAiRules".cooldown_s, coalesce("ClassAiRules".conditions::text, ''), "ClassAiRules".target, coalesce("ClassAiRules".min_level::text, ''), CASE WHEN "ClassAiRules".enabled IS FALSE THEN 'off' END))
  AND "ClassAiRules".seed_hash IS DISTINCT FROM EXCLUDED.seed_hash;

